class Solution {
public:
    int shoppingOffers(vector<int>& price, vector<vector<int>>& special, vector<int>& needs) {
        map<vector<int>, int> memo;
        auto dfs = [&](auto self, vector<int> cur) -> int {
            if (memo.count(cur)) return memo[cur];
            int cost = 0;
            for (size_t i = 0; i < cur.size(); ++i) cost += cur[i] * price[i];
            for (const auto& offer : special) {
                vector<int> nxt;
                for (size_t i = 0; i < cur.size(); ++i) {
                    if (cur[i] < offer[i]) break;
                    nxt.push_back(cur[i] - offer[i]);
                }
                if (nxt.size() == cur.size()) {
                    cost = min(cost, offer.back() + self(self, nxt));
                }
            }
            return memo[cur] = cost;
        };
        return dfs(dfs, needs);
    }
};

class Solution {
    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        Map<List<Integer>, Integer> memo = new HashMap<>();
        return dfs(price, special, needs, memo);
    }
    private int dfs(List<Integer> price, List<List<Integer>> special, List<Integer> cur, Map<List<Integer>, Integer> memo) {
        if (memo.containsKey(cur)) return memo.get(cur);
        int cost = 0;
        for (int i = 0; i < cur.size(); i++) cost += cur.get(i) * price.get(i);
        for (List<Integer> offer : special) {
            List<Integer> nxt = new ArrayList<>();
            for (int i = 0; i < cur.size(); i++) {
                if (cur.get(i) < offer.get(i)) break;
                nxt.add(cur.get(i) - offer.get(i));
            }
            if (nxt.size() == cur.size()) {
                cost = Math.min(cost, offer.get(offer.size() - 1) + dfs(price, special, nxt, memo));
            }
        }
        memo.put(cur, cost);
        return cost;
    }
}

var shoppingOffers = function(price, special, needs) {
    const memo = new Map();
    const dfs = (cur) => {
        const key = cur.join(',');
        if (memo.has(key)) return memo.get(key);
        let cost = 0;
        for (let i = 0; i < cur.length; i++) cost += cur[i] * price[i];
        for (const offer of special) {
            const nxt = [];
            for (let i = 0; i < cur.length; i++) {
                if (cur[i] < offer[i]) break;
                nxt.push(cur[i] - offer[i]);
            }
            if (nxt.length === cur.length) {
                cost = Math.min(cost, offer[offer.length - 1] + dfs(nxt));
            }
        }
        memo.set(key, cost);
        return cost;
    };
    return dfs(needs);
};
